fn weekly_billable_seconds(entries: &[TimeEntry]) -> BTreeMap<chrono::NaiveDate, i64> {
    let mut weeks = BTreeMap::new();
    for entry in entries {
        if !entry.billable || entry.stop.is_none() {
            continue;
        }

        let date = entry.start.date_naive();
        let monday = date - chrono::Duration::days(date.weekday().num_days_from_monday() as i64);
        *weeks.entry(monday).or_insert(0) += entry.duration;
    }
    weeks
}

impl BillWeeklyCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client
            .get_time_entries_filtered_minimal(since, until)
            .await?;
        let weeks = weekly_billable_seconds(&entries);

        if weeks.is_empty() {
            println!("(no data)");
            return Ok(());
        }

        let total: i64 = weeks.values().sum();
        for (week, seconds) in weeks {
            println!("{}  {seconds}s", week.format("%Y-%m-%d"));
        }
        println!("Total  {total}s");
        Ok(())
    }
}

